findings.suggestion:
// PATH starts a permalink's match at its host. A commit SHA holds no slash, so the path
// follows it; a named ref may (`feature/x`) and the path after it cannot be told from it,
// so every suffix of the remainder is a candidate, erring toward firing.
const paths = (areaText.match(PATH) ?? []).flatMap((path) => {
  const rest = path.replace(PERMALINK, '');
  const segments = rest.split('/');
  const candidates =
    rest === path
      ? [rest]
      : segments.length > 1 && /^[0-9a-f]{7,40}$/i.test(segments[0] ?? '')
        ? [segments.slice(1).join('/')]
        : segments.map((_, index) => segments.slice(index).join('/'));
  return candidates.map((candidate) => candidate.replace(/^\.\//, '').replace(/(?<!\.)\.+$/, ''));
});
